fn p(root:&str,n:&str)->PathBuf{Path::new(root).join(n)}
fn read(path:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(path).unwrap()).unwrap()}
fn hash(path:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(path).unwrap()))}
fn pins(path:impl AsRef<Path>)->usize{let a=read(path);for(k,h)in a.as_object().unwrap(){assert_eq!(hash(k),h.as_str().unwrap(),"pin{k}");}a.as_object().unwrap().len()}
fn managed(k:&str)->bool{["ZOPRO_","RAYON_","MALLOC_","CROSS_","CARGO_PROFILE_"].iter().any(|p|k.starts_with(p))||["RUSTFLAGS","RUSTDOCFLAGS","RUST_MIN_STACK","CARGO_TARGET_DIR","CARGO_BUILD_JOBS"].contains(&k)}
fn exit(root:&str,dir:&str,name:&str,success:bool)->Value{let base=p(root,&format!("{dir}/{name}"));let e=read(base.join("exit.json"));assert_eq!(e["success"],success);assert_eq!(e["returncode"],if success{0}else{101});for st in["stdout","stderr"]{assert_eq!(hash(base.join(format!("{st}.log"))),e[format!("{st}_sha256")].as_str().unwrap());}read(base.join("command.json"))}
fn workflow(root:&str,plan_name:&str,dir:&str)->usize{
    let plan=read(p(root,plan_name));let mut normalized=plan.clone();normalized.as_object_mut().unwrap().entry("environment").or_insert(json!({}));
    for step in normalized["steps"].as_array_mut().unwrap(){if step["kind"]=="command"{step.as_object_mut().unwrap().entry("environment").or_insert(json!({}));step.as_object_mut().unwrap().entry("unfiltered").or_insert(json!(false));step.as_object_mut().unwrap().entry("required_tests").or_insert(json!([]));}else if step["kind"]=="link-sdk"{step.as_object_mut().unwrap().entry("rustc_flags").or_insert(json!(["-O","-C","target-cpu=native","-C","lto=fat","-C","codegen-units=1"]));}}
    assert_eq!(normalized,read(p(root,&format!("{dir}/protocol.json"))));
    assert_eq!(read(p(root,&format!("{dir}/attempt-0.json")))["resume"],false);
    assert_eq!(read(p(root,&format!("{dir}/result.json")))["status"],"complete");
    for step in plan["steps"].as_array().unwrap(){let name=step["name"].as_str().unwrap();let c=exit(root,dir,name,true);let mut env=plan["environment"].as_object().cloned().unwrap_or_default();if let Some(e)=step["environment"].as_object(){env.extend(e.clone());}env.retain(|k,_|managed(k));assert_eq!(c["environment"],json!(env));if step["kind"]=="command"{assert!(c["argv"].as_array().unwrap().ends_with(step["argv"].as_array().unwrap()));}else{optimized(&c["argv"]);}}
    plan["steps"].as_array().unwrap().len()
}
fn optimized(v:&Value){let a=v.as_array().unwrap();assert_eq!(a.iter().filter(|v|**v=="-O").count(),1);for flag in["target-cpu=native","lto=fat","codegen-units=1"]{assert_eq!(a.windows(2).filter(|w|w[0]=="-C"&&w[1]==flag).count(),1);}}
